     type cloneSelection struct {
         roots    map[string]bool
         excluded map[string]bool
     }

     func newCloneSelection() cloneSelection {
         return cloneSelection{roots: map[string]bool{}, excluded: map[string]bool{}}
     }

     // includes: the nearest marked ancestor-or-self decides.
     func (s cloneSelection) includes(path string) bool {
         for p := path; p != ""; p = parentPath(p) {
             if s.excluded[p] { return false }
             if s.roots[p] { return true }
         }
         return false
     }

     func (s cloneSelection) toggle(path string) {
         if s.includes(path) {
             delete(s.roots, path)
             s.excluded[path] = true
             return
         }
         delete(s.excluded, path)
         s.roots[path] = true
     }

     func (s cloneSelection) state(path string) theme.CheckState {
         if s.includes(path) {
             if hasDescendant(s.excluded, path) { return theme.CheckSome }
             return theme.CheckAll
         }
         if hasDescendant(s.roots, path) { return theme.CheckSome }
         return theme.CheckNone
     }

     func (s cloneSelection) isEmpty() bool { return len(s.roots) == 0 }
     func (s cloneSelection) counts() (roots, exclusions int) { return len(s.roots), len(s.excluded) }
     func (s cloneSelection) rootPaths() []string { ... }

     func parentPath(path string) string {
         if i := strings.LastIndex(path, "/"); i > 0 { return path[:i] }
         return ""
     }

     // hasDescendant: the trailing separator is what keeps "acme/platform-tools"
     // from counting as a descendant of "acme/platform".
     func hasDescendant(set map[string]bool, path string) bool {
         prefix := path + "/"
         for p := range set {
             if strings.HasPrefix(p, prefix) { return true }
         }
         return false
     }
