input.content:
package explorer

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"

	tea "github.com/charmbracelet/bubbletea"
	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	"github.com/anthnel/devdesk/internal/gitlab"
)

// The clone pipeline: a discovery walk feeding a bounded pool of clones
// (§3.16, decision 7).
//
// Building the whole list first and then cloning it would only move the dead
// screen one step earlier — the walk is what takes the minutes. Here a
// repository becomes a row the moment it is found and starts cloning as soon as
// a slot frees, so the list fills and the count climbs while the work happens.
//
// Nothing here touches the model. Everything the run needs is copied into a
// cloneSpec before the first goroutine starts, and the only way back is the
// event channel (Rule 110).

// cloneEventKind is what happened to one path.
type cloneEventKind int

const (
	// cloneFound: discovery turned up a repository. The row appears.
	cloneFound cloneEventKind = iota
	// cloneBegan: a slot freed and `git clone` started. The row spins.
	cloneBegan
	// cloneEnded: the clone finished, was skipped, or failed.
	cloneEnded
	// cloneWalkFailed: a group could not be listed. It is reported as its own
	// row rather than folded into a repository's error, because the repositories
	// under it were never discovered and no other row can stand for them.
	cloneWalkFailed
)

type cloneEvent struct {
	kind    cloneEventKind
	path    string
	skipped bool
	err     error
}

// cloneEventBuffer keeps the workers off the UI's critical path. Three events
// per repository, so this absorbs a burst of some seventy without a worker
// waiting on Update.
const cloneEventBuffer = 256

// cloneSpec is everything a run needs, read out of the model up front.
type cloneSpec struct {
	client          *gitlabclient.Client
	roots           []*TreeNode
	selection       cloneSelection
	target          string
	cloneMethod     string
	gitlabURL       string
	jobs            int
	includeArchived bool
}

// cloneRun is a pipeline in flight.
type cloneRun struct {
	events <-chan cloneEvent
	// cancel stops **discovery only**. A `git clone` is never interrupted: a
	// context that kills one leaves half a repository on disk, which is exactly
	// the mess decision 12 exists to avoid. Cancelling therefore means the walk
	// stops and the scheduler issues no more work — the clones already running
	// are awaited, and the view says so.
	cancel context.CancelFunc
}

// startCloneRun launches the pipeline and returns immediately.
func startCloneRun(spec cloneSpec) *cloneRun {
	ctx, cancel := context.WithCancel(context.Background())
	events := make(chan cloneEvent, cloneEventBuffer)
	go runPipeline(ctx, spec, events)
	return &cloneRun{events: events, cancel: cancel}
}

// runPipeline walks the roots and clones what the walk finds.
func runPipeline(ctx context.Context, spec cloneSpec, events chan<- cloneEvent) {
	defer close(events)

	found := make(chan *TreeNode)
	go func() {
		defer close(found)
		for _, root := range spec.roots {
			discover(ctx, spec, root, found, events)
		}
	}()

	var wg sync.WaitGroup
	slots := make(chan struct{}, max(spec.jobs, 1))

	for node := range found {
		if ctx.Err() != nil {
			break
		}
		events <- cloneEvent{kind: cloneFound, path: node.FullPath}
		slots <- struct{}{}
		wg.Add(1)
		go func(n *TreeNode) {
			defer wg.Done()
			defer func() { <-slots }()

			events <- cloneEvent{kind: cloneBegan, path: n.FullPath}
			skipped, err := cloneOne(n, spec)
			events <- cloneEvent{kind: cloneEnded, path: n.FullPath, skipped: skipped, err: err}
		}(node)
	}

	// Drain rather than abandon. Breaking out of the loop above leaves the walker
	// parked on a send nobody will ever read, and a goroutine holding a live HTTP
	// client is a leak that outlives the view.
	//
	//nolint:revive // the drain is the point; there is nothing to do with a node here
	for range found {
	}
	wg.Wait()
}

// discover walks one root, sending every included project to the pool.
//
// The selection is consulted on the way down, so an excluded subtree costs no
// requests at all: the walk simply does not enter it.
func discover(ctx context.Context, spec cloneSpec, node *TreeNode, found chan<- *TreeNode, events chan<- cloneEvent) {
	if ctx.Err() != nil || !spec.selection.includes(node.FullPath) {
		return
	}

	if node.Type == NodeTypeProject {
		select {
		case found <- node:
		case <-ctx.Done():
		}
		return
	}

	children, err := discoverGroupChildren(spec.client, node, spec.includeArchived)
	if err != nil {
		// A cancelled walk reports nothing: the error is the cancellation, and a
		// failed row for it would read as a repository nobody could clone.
		if ctx.Err() == nil {
			events <- cloneEvent{kind: cloneWalkFailed, path: node.FullPath, err: err}
		}
		return
	}
	for _, child := range children {
		discover(ctx, spec, child, found, events)
	}
}

// cloneOne clones a repository, or reports that it was already there.
//
// The destination mirrors the forge path in full (decision 4). Keeping only the
// last segment, as the old pull did, made `acme/platform` and `other/platform`
// land on the same directory and merge — which could not happen while one
// subtree was cloned at a time, and can now that several roots are confirmed at
// once.
func cloneOne(node *TreeNode, spec cloneSpec) (skipped bool, err error) {
	dir := filepath.Join(spec.target, filepath.FromSlash(node.FullPath))
	if gitlab.DirExists(dir) {
		return true, nil
	}
	if err := os.MkdirAll(filepath.Dir(dir), 0o755); err != nil {
		return false, fmt.Errorf("mkdir %s: %w", filepath.Dir(dir), err)
	}
	if err := gitlab.Clone(cloneURL(spec.gitlabURL, spec.cloneMethod, node.FullPath), dir); err != nil {
		return false, err
	}
	return false, nil
}

// cloneURL builds the git URL for a project from the configured GitLab URL and
// the clone method. SSH form takes the host alone, so the scheme is stripped.
func cloneURL(gitlabURL, cloneMethod, fullPath string) string {
	cleanURL := strings.TrimSuffix(gitlabURL, "/")
	if cloneMethod != "ssh" {
		return fmt.Sprintf("%s/%s.git", cleanURL, fullPath)
	}

	host := strings.TrimPrefix(cleanURL, "https://")
	host = strings.TrimPrefix(host, "http://")
	return fmt.Sprintf("git@%s:%s.git", host, fullPath)
}

// waitForCloneEvent blocks on the run's channel and hands one event to Update.
// It is re-issued for each event, which is what keeps the model mutation in
// Update and the blocking read out of it.
func waitForCloneEvent(events <-chan cloneEvent) tea.Cmd {
	return func() tea.Msg {
		event, ok := <-events
		if !ok {
			return CloneRunFinishedMsg{}
		}
		return CloneEventMsg{event: event}
	}
}

package explorer

import (
	"strings"

	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// cloneState is what one row of the clone list is doing.
//
// There are five, and only five, because decision 2 draws the line: the
// explorer creates what is missing and never reconciles what exists. A dirty
// working copy, a diverged branch, a stale remote — none of them is a state
// here, they belong to the workspaces view (§3.17).
type cloneState int

const (
	cloneQueued cloneState = iota
	cloneRunning
	cloneCloned
	cloneAlreadyThere
	cloneFailed
)

// cloneRow is one repository, or one group whose walk failed.
type cloneRow struct {
	path  string
	state cloneState
	// frame is the spinner's current character, stamped on while the row is
	// running. It is text rather than a rendered spinner because a table cell
	// must carry no escape sequences (Rule 122).
	frame  string
	detail string
}

// cloneList is the ModeCloning screen: the pipeline in flight and the table
// showing it. It is the progress view and the report both — decision 9 leaves
// modals for yes/no confirmations only.
type cloneList struct {
	table datatable.Model[cloneRow]
	// rows is the authoritative order: discovery order, which is the order
	// things happened. The table may sort it, but the list does not.
	rows  []cloneRow
	index map[string]int

	run    *cloneRun
	target string
	frame  string

	// cancelling is set by `esc` and cleared by nothing: a run that is stopping
	// cannot be restarted, only awaited. A second `esc` must not force, because
	// forcing is the half-cloned directory decision 12 avoids.
	cancelling bool
	finished   bool
}

const (
	colCloneStatusMin = 16
	colClonePathMin   = 30
	colCloneDetailMin = 20
)

func newCloneList(target string, run *cloneRun) *cloneList {
	return &cloneList{
		target: target,
		run:    run,
		index:  map[string]int{},
		table: datatable.New(datatable.Config[cloneRow]{
			Columns: cloneColumns(),
			// Discovery order, deliberately: it is the order things happened, and
			// a list that reorders itself while it fills is unreadable. `.` still
			// sorts on demand.
			SortColumn: -1,
		}),
	}
}

// cloneColumns describes the clone list.
func cloneColumns() []datatable.Column[cloneRow] {
	return []datatable.Column[cloneRow]{
		{
			Title: "Status", MinWidth: colCloneStatusMin,
			Cell: func(r cloneRow) string { return cloneStatusLabel(r) },
			Less: func(a, b cloneRow) bool { return a.state < b.state },
		},
		{
			Title: "Repository", MinWidth: colClonePathMin, Flex: 2,
			Cell:   func(r cloneRow) string { return r.path },
			Less:   func(a, b cloneRow) bool { return strings.ToLower(a.path) < strings.ToLower(b.path) },
			Search: func(r cloneRow) string { return r.path },
		},
		{
			Title: "Detail", MinWidth: colCloneDetailMin, Flex: 1,
			Cell:   func(r cloneRow) string { return r.detail },
			Search: func(r cloneRow) string { return r.detail },
		},
	}
}

// cloneStatusLabel is the status cell: an icon and a word, plain text.
func cloneStatusLabel(r cloneRow) string {
	switch r.state {
	case cloneRunning:
		return r.frame + " cloning"
	case cloneCloned:
		return theme.IconOK + " cloned"
	case cloneAlreadyThere:
		return theme.IconSkipped + " already there"
	case cloneFailed:
		return theme.IconError + " failed"
	default:
		return theme.IconPending + " queued"
	}
}

// apply folds one pipeline event into the list.
//
// An event for a path that has no row yet creates one. That is not defensive
// padding: cloneWalkFailed names a group, which was never found as a
// repository and so has no row to update.
func (l *cloneList) apply(event cloneEvent) {
	switch event.kind {
	case cloneFound:
		l.upsert(event.path, cloneQueued, "")
	case cloneBegan:
		l.upsert(event.path, cloneRunning, "")
	case cloneEnded:
		switch {
		case event.err != nil:
			l.upsert(event.path, cloneFailed, event.err.Error())
		case event.skipped:
			l.upsert(event.path, cloneAlreadyThere, "")
		default:
			l.upsert(event.path, cloneCloned, "")
		}
	case cloneWalkFailed:
		l.upsert(event.path, cloneFailed, "discovery: "+event.err.Error())
	}
	l.sync()
}

func (l *cloneList) upsert(path string, state cloneState, detail string) {
	if i, ok := l.index[path]; ok {
		l.rows[i].state = state
		l.rows[i].detail = detail
		return
	}
	l.index[path] = len(l.rows)
	l.rows = append(l.rows, cloneRow{path: path, state: state, detail: detail})
}

// setFrame advances the spinner shown on the running rows.
func (l *cloneList) setFrame(frame string) {
	l.frame = frame
	l.sync()
}

// sync hands the table a copy with the current spinner frame stamped on.
//
// The frame is stamped here rather than held on the row because it belongs to
// the list, not to any repository: one spinner, on every row that is running.
func (l *cloneList) sync() {
	items := make([]cloneRow, len(l.rows))
	copy(items, l.rows)
	for i := range items {
		if items[i].state == cloneRunning {
			items[i].frame = l.frame
		}
	}
	l.table.SetItems(items)
}

// running counts the clones still in flight, which is what `esc` has to wait
// for and what the view states while it does.
func (l *cloneList) running() int {
	n := 0
	for _, r := range l.rows {
		if r.state == cloneRunning {
			n++
		}
	}
	return n
}

// counts is the header line: what has been found and how it went.
func (l *cloneList) counts() (found, cloned, present, failed int) {
	for _, r := range l.rows {
		found++
		switch r.state {
		case cloneCloned:
			cloned++
		case cloneAlreadyThere:
			present++
		case cloneFailed:
			failed++
		case cloneQueued, cloneRunning:
		}
	}
	return found, cloned, present, failed
}

// failures returns the failed paths, for the log and the footer. Decision 13
// discards the list on `esc`, and workspaces records only the successes — a
// failure that wrote nothing leaves nothing behind, so it has to be said while
// the view is still alive.
func (l *cloneList) failures() []string {
	var out []string
	for _, r := range l.rows {
		if r.state == cloneFailed {
			out = append(out, r.path)
		}
	}
	return out
}

package explorer

import (
	"log"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
)

// The clone flow, end to end (§3.16):
//
//	c              → ModeSelecting, the tree with checkboxes
//	space          → tick the row; ←→ still drill, so deselecting means going in
//	enter          → borrow the workspaces view for a destination
//	                 (the selection survives the round trip — it names paths)
//	destination    → ModeCloning, the pipeline starts
//	esc            → cancel: discovery stops, running clones are awaited
//	esc (finished) → back to the tree, list discarded (decision 13)

// handleCloneStart enters the selection mode.
func (m Model) handleCloneStart() (tea.Model, tea.Cmd) {
	if m.shared.GitLabClient == nil || len(m.nodes) == 0 {
		return m, nil
	}
	m.mode = ModeSelecting
	m.selection = newCloneSelection()
	m.selectionNodes = map[string]*TreeNode{}
	m.updateTableRows()
	return m, nil
}

// handleSelectionToggle ticks or unticks the row under the cursor (Space,
// Rule 135).
//
// The node is kept beside the path because the walk needs somewhere to start
// and a root ticked three levels down is not reachable from the current level
// once the user has come back up. The selection itself stays paths-only — it
// has to answer for descendants nobody has fetched.
func (m Model) handleSelectionToggle() (tea.Model, tea.Cmd) {
	node, ok := m.selectedNode()
	if !ok {
		return m, nil
	}

	m.selection.toggle(node.FullPath)
	if m.selection.isRoot(node.FullPath) {
		m.selectionNodes[node.FullPath] = node
	} else {
		delete(m.selectionNodes, node.FullPath)
	}
	m.updateTableRows()
	return m, nil
}

// handleSelectionConfirm asks the app for a destination directory.
func (m Model) handleSelectionConfirm() (tea.Model, tea.Cmd) {
	if m.selection.isEmpty() {
		m.footerInfo = "Nothing selected — press space to tick a group or a project"
		return m, clearFooterMsgCmd()
	}
	return m, func() tea.Msg { return CloneSelectionRequestMsg{} }
}

// handleSelectionCancel leaves the selection mode, dropping the selection.
func (m Model) handleSelectionCancel() (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.selection = newCloneSelection()
	m.selectionNodes = nil
	m.updateTableRows()
	return m, nil
}

// handleCloneDestinationSelected starts the pipeline.
func (m Model) handleCloneDestinationSelected(msg CloneDestinationSelectedMsg) (tea.Model, tea.Cmd) {
	roots := m.rootNodes()
	if len(roots) == 0 {
		// The selection survived the round trip but named nothing reachable,
		// which is a bug rather than a user action — say so instead of opening
		// an empty list.
		log.Printf("ERROR [explorer] clone: the selection resolved to no nodes")
		m.footerError = "Nothing to clone — check logs"
		return m.handleSelectionCancel()
	}

	run := startCloneRun(cloneSpec{
		client:          m.shared.GitLabClient,
		roots:           roots,
		selection:       m.selection,
		target:          msg.Path,
		cloneMethod:     m.config.GitLab.CloneMethod,
		gitlabURL:       m.config.GitLab.URL,
		jobs:            m.config.GitLab.Pull.ParallelJobs,
		includeArchived: m.config.GitLab.Pull.IncludeArchived,
	})

	m.mode = ModeCloning
	m.clone = newCloneList(msg.Path, run)
	m.clone.table.Resize(m.width, max(m.height-1, 1))
	return m, tea.Batch(m.spinner.Tick, waitForCloneEvent(run.events))
}

// rootNodes resolves the ticked paths to the nodes the walk starts from, in a
// stable order so two runs of the same selection read the same way.
func (m Model) rootNodes() []*TreeNode {
	paths := m.selection.rootPaths()
	nodes := make([]*TreeNode, 0, len(paths))
	for _, path := range paths {
		if node, ok := m.selectionNodes[path]; ok {
			nodes = append(nodes, node)
		}
	}
	return nodes
}

// handleCloneEvent folds one pipeline event in and waits for the next.
func (m Model) handleCloneEvent(msg CloneEventMsg) (tea.Model, tea.Cmd) {
	if m.clone == nil {
		return m, nil
	}
	if msg.event.kind == cloneEnded && msg.event.err != nil {
		log.Printf("ERROR [explorer] clone %s: %v", msg.event.path, msg.event.err)
	}
	if msg.event.kind == cloneWalkFailed {
		log.Printf("ERROR [explorer] discover %s: %v", msg.event.path, msg.event.err)
	}
	m.clone.apply(msg.event)
	return m, waitForCloneEvent(m.clone.run.events)
}

// handleCloneRunFinished is the closed channel: every clone has returned.
func (m Model) handleCloneRunFinished() (tea.Model, tea.Cmd) {
	if m.clone == nil {
		return m, nil
	}
	m.clone.finished = true

	// Decision 13 keeps only what workspaces can show, and a failed clone wrote
	// nothing. Naming the failures now is the only record there will be.
	if failed := m.clone.failures(); len(failed) > 0 {
		m.footerError = failureSummary(failed)
		return m, clearFooterMsgCmd()
	}
	return m, nil
}

// failureSummary names one failure and counts the rest — the footer is one line.
func failureSummary(failed []string) string {
	if len(failed) == 1 {
		return "Failed to clone " + failed[0] + " — check logs"
	}
	return "Failed to clone " + failed[0] + " and " +
		plural(len(failed)-1, "other") + " — check logs"
}

func plural(n int, word string) string {
	if n == 1 {
		return "1 " + word
	}
	return itoa(n) + " " + word + "s"
}

// handleCloneEsc cancels a running pipeline, or closes a finished one.
//
// The two are one key because they are one intent — "I am done with this" — and
// separating them would need the user to know which state the list is in. A
// second press while cancelling does nothing: forcing would mean killing a
// `git clone` mid-write, which is the half-repository decision 12 rules out.
func (m Model) handleCloneEsc() (tea.Model, tea.Cmd) {
	if m.clone == nil {
		m.mode = ModeNormal
		return m, nil
	}
	if m.clone.finished {
		return m.handleCloneClose()
	}
	if m.clone.cancelling {
		return m, nil
	}

	m.clone.cancelling = true
	m.clone.run.cancel()
	return m, nil
}

// handleCloneClose discards the list and returns to the tree.
func (m Model) handleCloneClose() (tea.Model, tea.Cmd) {
	m.clone = nil
	m.selection = newCloneSelection()
	m.selectionNodes = nil
	m.mode = ModeNormal
	m.updateTableRows()
	return m, nil
}

// cloneStatusLine is what the view puts under the list: what the run is doing,
// then what it did.
func (m Model) cloneStatusLine() string {
	if m.clone == nil {
		return ""
	}
	found, cloned, present, failed := m.clone.counts()

	var b strings.Builder
	switch {
	case m.clone.finished:
		b.WriteString("Done — ")
	case m.clone.cancelling:
		b.WriteString("Cancelling — " + plural(m.clone.running(), "clone") + " finishing · ")
	default:
		b.WriteString(itoa(found) + " found · ")
	}
	b.WriteString(itoa(cloned) + " cloned · " + itoa(present) + " already there")
	if failed > 0 {
		b.WriteString(" · " + itoa(failed) + " failed")
