	if m.shared.GitLabClient == nil || m.loading || m.error != "" || len(m.nodes) == 0 {
		return false
	}
	if m.creationForm != nil {
		return false
	}
	switch m.mode {
	case ModeNormal, ModeSelecting:
		return true
	default:
		return false
	}
}

