     type CloneOptions struct {
         Token string  // authenticates over HTTPS; empty for SSH / public repos
     }

     func Clone(repoURL, targetPath string, opts CloneOptions) error {
         cmd := exec.Command("git", "clone", repoURL, targetPath)
         cmd.Env = cloneEnv(opts)
         var stderr bytes.Buffer
         cmd.Stdin = nil
         cmd.Stdout = nil
         cmd.Stderr = &stderr
         if err := cmd.Run(); err != nil {
             if reason := lastLine(stderr.String()); reason != "" {
                 return fmt.Errorf("%s", reason)
             }
             return err
         }
         return nil
     }

     func cloneEnv(opts CloneOptions) []string {
         env := append(os.Environ(),
             "GIT_TERMINAL_PROMPT=0",
             "GCM_INTERACTIVE=never",
             "GIT_ASKPASS=",
             "SSH_ASKPASS=",
             "GIT_SSH_COMMAND=ssh -o BatchMode=yes",
         )
         config := [][2]string{
             {"http.lowSpeedLimit", "1000"},
             {"http.lowSpeedTime", "60"},
         }
         if opts.Token != "" {
             credential := base64.StdEncoding.EncodeToString([]byte("oauth2:" + opts.Token))
             config = append(config, [2]string{"http.extraHeader", "Authorization: Basic " + credential})
         }
         env = append(env, fmt.Sprintf("GIT_CONFIG_COUNT=%d", len(config)))
         for i, kv := range config {
             env = append(env,
                 fmt.Sprintf("GIT_CONFIG_KEY_%d=%s", i, kv[0]),
                 fmt.Sprintf("GIT_CONFIG_VALUE_%d=%s", i, kv[1]),
             )
         }
         return env
     }

     func lastLine(output string) string {
         lines := strings.Split(strings.ReplaceAll(output, "\r", "\n"), "\n")
         for i := len(lines) - 1; i >= 0; i-- {
             if line := strings.TrimSpace(lines[i]); line != "" { return line }
         }
         return ""
     }
