305	func (m Model) GetShortcuts() shortcut.Shortcuts {
306		// Mode input
307		if m.mode == ModeAdding {
308			return []shortcut.Shortcut{
309				{Key: "enter", Description: "Create"},
310				{Key: "esc", Description: "Cancel"},
311			}
312		}
313	
314		// Mode renaming
315		if m.mode == ModeRenaming {
316			return []shortcut.Shortcut{
317				{Key: "enter", Description: "Rename"},
318				{Key: "esc", Description: "Cancel"},
319			}
320		}
321	
322		// Mode confirm
323		if m.mode == ModeConfirmingDelete {
324			return []shortcut.Shortcut{
325				{Key: "y/n", Description: "Confirm"},
326				{Key: "esc", Description: "Cancel"},
327			}
328		}
329	
330		// Selection mode
331		if m.mode == ModeSelecting {
332			return []shortcut.Shortcut{
333				{Key: "←→", Description: "Open/Back"},
334				{Key: "enter", Description: "Select"},
335				{Key: "esc", Description: "Back/Cancel"},
336			}
337		}
338	
339		// Normal mode — determine selected entry state for dynamic shortcuts (Rule 130)
340		var selectedEntry *Entry
341		if entry, ok := m.selectedEntry(); ok {
342			selectedEntry = &entry
343		}
344	
345		isGitRepo := selectedEntry != nil && selectedEntry.IsGitRepo
346		var hasScanResult bool
347		if isGitRepo {
348			_, hasScanResult = m.scanCache[selectedEntry.Path]
349		}
350		hasSubRepos := selectedEntry != nil && !isGitRepo && len(selectedEntry.SubRepoPaths) > 0
351	
352		shortcuts := []shortcut.Shortcut{
353			{Key: "←→", Description: "Open/Back"},
354		}
355	
356		// enter: only shown for git repos with cached scan results
357		if hasScanResult {
358			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "enter", Description: "Scan details"})
359		}
360	
361		shortcuts = append(shortcuts,
362			shortcut.Shortcut{Key: "t", Description: "Terminal (in-place)"},
363			shortcut.Shortcut{Key: "T", Description: "Terminal (new window)"},
364			shortcut.Shortcut{Key: "ctrl+o", Description: "IDE"},
365		)
366	
367		// ctrl+w: only shown for git repos
368		if isGitRepo {
369			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "ctrl+w", Description: "Browser"})
370		}
371	
372		// ctrl+s: shown for git repos and directories with nested repos
373		if isGitRepo || hasSubRepos {
374			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "ctrl+s", Description: "Scan"})
375		}
376	
377		shortcuts = append(shortcuts,
378			shortcut.Shortcut{Key: "A", Description: "Scan unscanned"},
379			shortcut.Shortcut{Key: "ctrl+a", Description: "Scan all"},
380		)
381	
382		// ctrl+n: hidden when a git repo is selected
383		if !isGitRepo {
384			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "ctrl+n", Description: "New directory"})
385		}
386	
387		shortcuts = append(shortcuts,
388			shortcut.Shortcut{Key: "r", Description: "Rename"},
389			shortcut.Shortcut{Key: "ctrl+d", Description: "Delete"},
390			shortcut.Shortcut{Key: "ctrl+r", Description: "Refresh"},
391			shortcut.Shortcut{Key: "/", Description: "Search"},
392			shortcut.Shortcut{Key: "alt+:", Description: "Command"},
393			shortcut.Shortcut{Key: "?", Description: "Help"},
