91	// requestScanAll triggers batch scanning of all git repos visible in the current view,
92	// purging in-memory and disk cache first (Rule 126).
93	func (m Model) requestScanAll() (tea.Model, tea.Cmd) {
94		paths := m.collectAllRepoPaths()
95		if len(paths) == 0 {
96			return m, nil
97		}
98		// Purge in-memory cache synchronously (Update() is thread-safe)
99		for _, path := range paths {
100			delete(m.scanCache, path)
101		}
102		return m, tea.Batch(deleteScanCacheCmd(paths), batchScanCmd(paths, scan.OptionsFromConfig(m.config.Scan)))
103	}
