105	// collectAllRepoPaths returns all git repo paths visible in the current view,
106	// including sub-repos nested within non-git directories.
107	func (m Model) collectAllRepoPaths() []string {
108		var paths []string
109		for _, entry := range m.entries() {
110			if entry.IsGitRepo {
111				paths = append(paths, entry.Path)
112			} else if len(entry.SubRepoPaths) > 0 {
113				paths = append(paths, entry.SubRepoPaths...)
114			}
115		}
116		return paths
117	}
