119	// handleWorkspaceScanComplete processes the result of a completed workspace scan (Rule 128).
120	func (m Model) handleWorkspaceScanComplete(msg WorkspaceScanCompleteMsg) (tea.Model, tea.Cmd) {
121		delete(m.scanningPaths, msg.RepoPath)
122		if msg.Error != nil {
123			log.Printf("ERROR [workspaces] scan complete %s: %v", msg.RepoPath, msg.Error)
124			m.footerError = "Scan failed — check logs"
125			m.refreshRows()
126			return m, clearFooterInfoCmd()
127		}
128		m.footerError = ""
129		m.scanCache[msg.RepoPath] = cache.WorkspaceScanEntry{
130			RepoPath:  msg.RepoPath,
131			Critical:  msg.Critical,
132			High:      msg.High,
133			Medium:    msg.Medium,
134			Low:       msg.Low,
135			Sensitive: msg.Sensitive,
136			ScannedAt: msg.ScannedAt,
137		}
138		m.refreshRows()
139		return m, nil
140	}
