164	// openTerminalWindow opens a new terminal window at the target directory.
165	// Resolution order:
166	//  1. config.App.TerminalCommand override → detached process (non-blocking)
167	//  2. Auto-detect from environment → detached process (non-blocking)
168	//  3. No fallback — shows a footer error (does not work on WSL)
169	func (m Model) openTerminalWindow() (tea.Model, tea.Cmd) {
170		targetPath := m.resolveTargetPath()
171	
172		// Config override: e.g. "kitty --directory"
173		if m.config.App.TerminalCommand != "" {
