50	// It emits WorkspaceScanStartingMsg before scanning and WorkspaceScanCompleteMsg after.
51	func scanOneRepoCmd(repoPath string, opts scan.ScanOptions, sem chan struct{}) tea.Cmd {
52		return tea.Sequence(
53			func() tea.Msg {
54				return WorkspaceScanStartingMsg{RepoPath: repoPath}
55			},
56			func() tea.Msg {
57				sem <- struct{}{}
58				defer func() { <-sem }()
59	
60				scanner := scan.NewScanner(opts)
61				result, err := scanner.Scan(context.Background(), repoPath, scan.TargetDirectory)
62				if err != nil {
63					log.Printf("ERROR [workspaces] scan %s: %v", repoPath, err)
64					return WorkspaceScanCompleteMsg{
65						RepoPath: repoPath,
66						Error:    err,
67					}
68				}
69	
70				if len(result.Errors) > 0 && result.TotalFindings() == 0 {
71					combined := strings.Join(result.Errors, "; ")
72					log.Printf("ERROR [workspaces] scan errors for %s: %s", repoPath, combined)
73				}
74	
75				sensitive := false
76				for _, f := range result.Findings {
77					if f.Source == "gitleaks" {
78						sensitive = true
79						break
80					}
81				}
82	
83				entry := cache.WorkspaceScanEntry{
84					RepoPath:  repoPath,
85					Critical:  result.Counts.Critical,
86					High:      result.Counts.High,
87					Medium:    result.Counts.Medium,
88					Low:       result.Counts.Low,
89					Sensitive: sensitive,
90					ScannedAt: result.EndTime,
91				}
92	
93				wc, cErr := cache.NewWorkspaceScanCache(config.CurrentContextName())
94				if cErr != nil {
95					log.Printf("ERROR [workspaces] open cache: %v", cErr)
96				} else if sErr := wc.Set(repoPath, entry); sErr != nil {
97					log.Printf("ERROR [workspaces] cache set %s: %v", repoPath, sErr)
98				}
99	
100				if sErr := cache.SaveWorkspaceScanResult(repoPath, result); sErr != nil {
101					log.Printf("ERROR [workspaces] save full result %s: %v", repoPath, sErr)
102				}
103	
104				return WorkspaceScanCompleteMsg{
105					RepoPath:  repoPath,
106					Critical:  entry.Critical,
107					High:      entry.High,
108					Medium:    entry.Medium,
109					Low:       entry.Low,
110					Sensitive: sensitive,
111					ScannedAt: entry.ScannedAt,
112				}
113			},
114		)
115	}
116	
117	// batchScanCmd scans all provided repo paths in parallel using a worker pool
118	// of runtime.NumCPU()/2 workers (minimum 1).
119	func batchScanCmd(repoPaths []string, opts scan.ScanOptions) tea.Cmd {
120		numWorkers := runtime.NumCPU() / 2
121		if numWorkers < 1 {
122			numWorkers = 1
123		}
124		sem := make(chan struct{}, numWorkers)
125	
126		cmds := make([]tea.Cmd, len(repoPaths))
127		for i, path := range repoPaths {
128			cmds[i] = scanOneRepoCmd(path, opts, sem)
129		}
130		return tea.Batch(cmds...)
131	}
