	if m.footerError != "" {
		return theme.PadWithBg(theme.StatusErrorStyle.Render(m.footerError), width)
	}
	text := m.footerInfo
	if line := m.syncStatusLine(); line != "" {
		text = line
	}
	if text == "" {
